<script lang="ts">
  import { onMount } from 'svelte';
  import { ArrowLeft, Gamepad2, Mic2, Users, Clock3 } from '@lucide/svelte';
  import Dropdown, { type DropdownOption } from '$lib/components/ui/Dropdown.svelte';
  import { featureApiJson } from '$lib/client/feature-api.js';
  import { notify } from '$lib/client/notifications.js';
  const { data } = $props() as { data:{slug:string} };
  type Session={id:string;game:string;platform:string;region:string;rank:string|null;activity:string;title:string;description:string|null;partySize:number;slotsOpen:number;voiceRequired:boolean;status:string;expiresAt:string;createdAt:string;hostUsername:string|null;hostName:string|null;joinedCount:number;myStatus:string|null};
  let sessions=$state<Session[]>([]); let loading=$state(true); let busy=$state(false); let creating=$state(false); let error=$state(''); let joinBusy=$state('');
  let game=$state('');let platform=$state('Any');let region=$state('Any');let rank=$state('');let activity=$state('casual');let title=$state('');let description=$state('');let partySize=$state('5');let slotsOpen=$state('4');let voiceRequired=$state(false);let expiresInMinutes=$state('120');
  const platformOptions:DropdownOption[]=['Any','PC','PlayStation','Xbox','Nintendo Switch','Mobile','Cross-play'].map(v=>({value:v,label:v}));
  const activityOptions:DropdownOption[]=[{value:'casual',label:'Casual'},{value:'ranked',label:'Ranked'},{value:'competitive',label:'Competitive'},{value:'co-op',label:'Co-op'},{value:'raid',label:'Raid'},{value:'tournament',label:'Tournament'}];
  async function load(){loading=true;error='';try{const r=await featureApiJson<{sessions:Session[]}>(`/communities/${encodeURIComponent(data.slug)}/lfg`);sessions=r.sessions;}catch(e){error=e instanceof Error?e.message:'Could not load LFG sessions.';}finally{loading=false;}}
  async function create(){if(!game.trim()||!title.trim()){error='Add a game and session title.';return;}busy=true;error='';try{await featureApiJson(`/communities/${encodeURIComponent(data.slug)}/lfg`,{method:'POST',body:JSON.stringify({game,platform,region,rank,activity,title,description,partySize:Number(partySize),slotsOpen:Number(slotsOpen),voiceRequired,expiresInMinutes:Number(expiresInMinutes)})});title='';description='';creating=false;notify('Looking-for-group session created.','success');await load();}catch(e){error=e instanceof Error?e.message:'Could not create a session.';notify(error,'error');}finally{busy=false;}}
  async function join(item:Session){joinBusy=item.id;try{if(item.myStatus){await featureApiJson(`/lfg/${encodeURIComponent(item.id)}/join`,{method:'DELETE'});}else{await featureApiJson(`/lfg/${encodeURIComponent(item.id)}/join`,{method:'POST'});}await load();}catch(e){notify(e instanceof Error?e.message:'Could not update party membership.','error');}finally{joinBusy='';}}
  async function close(item:Session){try{await featureApiJson(`/lfg/${encodeURIComponent(item.id)}/close`,{method:'PATCH'});notify('LFG session closed.','success');await load();}catch(e){notify(e instanceof Error?e.message:'Could not close session.','error');}}
  onMount(()=>{void load();});
</script>
<svelte:head><title>Looking for group · c/{data.slug} · Nexus</title></svelte:head>
<div class="mx-auto w-full max-w-[1500px] px-3 pb-20 sm:px-6"><a href={`/c/${encodeURIComponent(data.slug)}`} class="inline-flex items-center gap-2 text-xs font-bold text-slate-400 hover:text-white"><ArrowLeft size={15}/> c/{data.slug}</a>
<header class="mt-4 flex flex-wrap items-end justify-between gap-4 border-b border-white/10 pb-5"><div><div class="flex items-center gap-2 text-xs font-bold uppercase tracking-widest text-orange-300"><Gamepad2 size={16}/> Gaming hub</div><h1 class="mt-2 text-3xl font-black text-white">Find your squad</h1><p class="mt-2 text-sm text-slate-400">Match by game, platform, region, rank, and activity.</p></div><button onclick={()=>creating=!creating} class="rounded-full bg-orange-400 px-4 py-2.5 text-sm font-extrabold text-slate-950">{creating?'Cancel':'＋ Find a group'}</button></header>
{#if creating}<section class="mt-4 rounded-xl border border-white/10 bg-[#101719] p-4"><h2 class="font-extrabold text-white">New LFG session</h2><div class="mt-4 grid gap-3 sm:grid-cols-2 xl:grid-cols-3"><label class="grid gap-1.5 text-xs font-bold text-slate-300">Game<input bind:value={game} maxlength="80" class="rounded-lg border border-white/10 bg-black/20 p-3 text-sm text-white" placeholder="Valorant, Minecraft, Genshin…"/></label><label class="grid gap-1.5 text-xs font-bold text-slate-300">Platform<Dropdown label="Platform" options={platformOptions} value={platform} onChange={v=>platform=v} fullWidth/></label><label class="grid gap-1.5 text-xs font-bold text-slate-300">Region<input bind:value={region} maxlength="60" class="rounded-lg border border-white/10 bg-black/20 p-3 text-sm text-white" placeholder="SEA, NA, EU…"/></label><label class="grid gap-1.5 text-xs font-bold text-slate-300">Activity<Dropdown label="Activity" options={activityOptions} value={activity} onChange={v=>activity=v} fullWidth/></label><label class="grid gap-1.5 text-xs font-bold text-slate-300">Rank / level<input bind:value={rank} maxlength="80" class="rounded-lg border border-white/10 bg-black/20 p-3 text-sm text-white" placeholder="Optional rank or experience"/></label><label class="grid gap-1.5 text-xs font-bold text-slate-300">Party size<input bind:value={partySize} type="number" min="2" max="100" class="rounded-lg border border-white/10 bg-black/20 p-3 text-sm text-white"/></label><label class="grid gap-1.5 text-xs font-bold text-slate-300">Open slots<input bind:value={slotsOpen} type="number" min="1" max="99" class="rounded-lg border border-white/10 bg-black/20 p-3 text-sm text-white"/></label><label class="grid gap-1.5 text-xs font-bold text-slate-300">Auto-close after<Dropdown label="Session duration" options={[{value:'30',label:'30 minutes'},{value:'60',label:'1 hour'},{value:'120',label:'2 hours'},{value:'360',label:'6 hours'},{value:'720',label:'12 hours'},{value:'1440',label:'24 hours'}]} value={expiresInMinutes} onChange={v=>expiresInMinutes=v} fullWidth/></label><label class="flex items-center gap-2 text-xs font-bold text-slate-300"><input bind:checked={voiceRequired} type="checkbox"/> Voice chat required</label><label class="grid gap-1.5 text-xs font-bold text-slate-300 sm:col-span-2 xl:col-span-3">Session title<input bind:value={title} maxlength="120" class="rounded-lg border border-white/10 bg-black/20 p-3 text-sm text-white" placeholder="Chill co-op, ranked push, weekly raid…"/></label><label class="grid gap-1.5 text-xs font-bold text-slate-300 sm:col-span-2 xl:col-span-3">Details<textarea bind:value={description} rows="3" maxlength="1000" class="rounded-lg border border-white/10 bg-black/20 p-3 text-sm text-white"/></label></div>{#if error}<p role="alert" class="mt-3 text-sm text-rose-200">{error}</p>{/if}<div class="mt-4 flex justify-end"><button onclick={create} disabled={busy} class="rounded-full bg-orange-400 px-4 py-2.5 text-sm font-extrabold text-slate-950 disabled:opacity-50">{busy?'Creating…':'Post LFG session'}</button></div></section>{/if}
{#if error && !creating}<p role="alert" class="mt-4 rounded-xl border border-rose-300/20 p-3 text-sm text-rose-200">{error}</p>{/if}
{#if loading}<p class="mt-8 text-sm text-slate-400">Finding active sessions…</p>{:else if !sessions.length}<div class="mt-5 rounded-xl border border-dashed border-white/15 p-10 text-center"><Gamepad2 size={32} class="mx-auto text-slate-500"/><h2 class="mt-3 font-bold text-white">No one is looking for a group yet</h2><p class="mt-2 text-sm text-slate-400">Start a session so players can find you.</p></div>{:else}<div class="mt-5 grid gap-3 md:grid-cols-2 xl:grid-cols-3">{#each sessions as item (item.id)}<article class="rounded-xl border border-white/10 bg-[#101719] p-4"><div class="flex items-center justify-between gap-3"><span class="rounded-full bg-orange-400/10 px-2 py-1 text-[10px] font-extrabold uppercase text-orange-300">{item.activity}</span><span class="text-[10px] text-slate-500">{item.platform} · {item.region}</span></div><h2 class="mt-3 text-lg font-extrabold text-white">{item.title}</h2><div class="mt-1 text-xs font-semibold text-orange-200">{item.game}{item.rank?` · ${item.rank}`:''}</div>{#if item.description}<p class="mt-2 text-sm leading-5 text-slate-400">{item.description}</p>{/if}<div class="mt-4 flex flex-wrap gap-x-3 gap-y-2 text-xs text-slate-400"><span class="flex items-center gap-1"><Users size={14}/>{item.slotsOpen} slots open</span>{#if item.voiceRequired}<span class="flex items-center gap-1"><Mic2 size={14}/>Voice required</span>{/if}<span class="flex items-center gap-1"><Clock3 size={14}/>Ends {new Date(item.expiresAt).toLocaleTimeString([], {hour:'numeric',minute:'2-digit'})}</span></div><div class="mt-4 flex items-center justify-between border-t border-white/[.07] pt-3"><span class="text-[11px] text-slate-500">Host u/{item.hostUsername||item.hostName||'member'}</span><div class="flex gap-2"><button onclick={()=>void join(item)} disabled={joinBusy===item.id} class="rounded-full border border-white/10 px-3 py-2 text-xs font-bold text-slate-200 hover:border-orange-300/40 disabled:opacity-50">{joinBusy===item.id?'…':item.myStatus?'Leave':'Join party'}</button>{#if item.myStatus==='joined' && item.slotsOpen<item.partySize}<span class="self-center text-[10px] text-emerald-300">Joined</span>{/if}</div></div></article>{/each}</div>{/if}</div>
